window.CREP_BANK = {"qcm": [{"topic": "Bâtiment", "pages": [3], "id": "q1", "prompt": "Quel est le rôle principal de l’ossature d’un bâtiment ?", "options": ["Supporter les charges et les efforts", "Assurer seulement la décoration", "Remplacer tous les isolants", "Évacuer uniquement les eaux"], "correct": [0], "explanation": "Elle supporte les efforts du bâtiment. Exemples : poids propre, occupants et mobilier, neige ou sollicitations sismiques."}, {"topic": "Bâtiment", "pages": [7], "id": "q2", "prompt": "Quel plancher est caractéristique du mode constructif 1900–1920 décrit dans le cours ?", "options": ["Un solivage bois", "Une dalle alvéolaire précontrainte systématique", "Un plancher exclusivement en PVC", "Une dalle sur bac acier généralisée"], "correct": [0], "explanation": "Les planchers sont fréquemment en solives de bois. La portée limitée des solives nécessite des murs de refend."}, {"topic": "Bâtiment", "pages": [8], "id": "q3", "prompt": "Quelle association caractérise la construction de 1920 à 1945 ?", "options": ["Savoir-faire traditionnels et nouveaux matériaux industriels", "Abandon total de la pierre et du bois", "Usage exclusif du béton préfabriqué", "Absence de matériaux industriels"], "correct": [0], "explanation": "La pierre et le bois restent employés. Ils coexistent avec le béton, le ciment, le métal ou les produits des filières industrielles locales."}, {"topic": "Bâtiment", "pages": [9], "id": "q4", "prompt": "Quelle évolution marque la période 1945–1975 ?", "options": ["La généralisation des matériaux industriels et la normalisation", "La disparition du chauffage central", "L’abandon du ciment", "Le retour exclusif aux techniques rurales"], "correct": [0], "explanation": "Les matériaux industriels se généralisent et les procédés se normalisent. Le chauffage central se diffuse ; le béton prend une place importante."}, {"topic": "Bâtiment", "pages": [14], "id": "q5", "prompt": "Qu’appelle-t-on le fonds servant ?", "options": ["La propriété qui supporte la servitude", "La propriété qui bénéficie de la servitude", "Le propriétaire du matériel de diagnostic", "Une réserve financière de copropriété"], "correct": [0], "explanation": "Le fonds servant supporte la contrainte. Le fonds dominant bénéficie de cette servitude, attachée au bien."}, {"topic": "Plomb et exposition", "pages": [27], "id": "q6", "prompt": "Quel est le principal minerai du plomb cité dans le support ?", "options": ["La galène, PbS", "La calcite, CaCO₃", "Le quartz, SiO₂", "La magnétite, Fe₃O₄"], "correct": [0], "explanation": "Il s’agit de la galène. Sa formule est PbS."}, {"topic": "Plomb et exposition", "pages": [28], "id": "q7", "prompt": "Quelle propriété facilite le travail du plomb ?", "options": ["Sa malléabilité", "Son extrême fragilité", "Sa transparence", "Son absence de masse"], "correct": [0], "explanation": "Le plomb est malléable et facile à travailler. Sa forte densité ou son bas point de fusion est cité ; accepter aussi son aspect gris bleuâtre."}, {"topic": "Plomb et exposition", "pages": [31], "id": "q8", "prompt": "Que matérialise un fil à plomb ?", "options": ["La direction de la pesanteur", "Une concentration de plomb", "La résistance thermique d’un mur", "La teneur en eau d’une peinture"], "correct": [0], "explanation": "C’est un fil lesté. Il donne la direction de la pesanteur, donc la verticale."}, {"topic": "Plomb et exposition", "pages": [32], "id": "q9", "prompt": "Quelle est la couleur du pigment appelé céruse ?", "options": ["Blanche", "Bleue", "Verte", "Noire"], "correct": [0], "explanation": "C’est un pigment blanc à base de plomb. Il a été utilisé dans les peintures ou dans les fards et cosmétiques."}, {"topic": "Plomb et exposition", "pages": [33], "id": "q10", "prompt": "À quel usage du bâtiment le minium est-il notamment associé ?", "options": ["Aux peintures antirouille", "Aux isolants en laine de verre", "Aux joints exclusivement en silicone", "Aux vitrages sans revêtement"], "correct": [0], "explanation": "C’est un pigment au plomb, notamment utilisé comme antirouille. Le ponçage ou le brûlage peut libérer du plomb et provoquer une exposition toxique."}, {"topic": "Plomb et exposition", "pages": [36], "id": "q11", "prompt": "Quelle source d’exposition domine dans l’habitat ancien selon le cours ?", "options": ["Les anciennes peintures à la céruse", "Les vitrages nus", "Le bois brut non traité", "Les joints neufs sans plomb"], "correct": [0], "explanation": "Une peinture à la céruse peut se dégrader, notamment avec l’humidité. Des écailles et poussières sont libérées puis ingérées ou inhalées."}, {"topic": "Plomb et exposition", "pages": [37], "id": "q12", "prompt": "Quelle autre source de plomb peut exister dans un logement ?", "options": ["L’eau passant dans des canalisations en plomb", "L’eau déminéralisée garantie sans plomb", "Une vitre nue systématiquement", "L’air neuf nécessairement dépourvu de toute pollution"], "correct": [0], "explanation": "Premier exemple pertinent : eau circulant dans des canalisations en plomb, poussières professionnelles ou industrielles. Second exemple distinct : céramiques artisanales, cosmétiques traditionnels, jouets au plomb ou certains loisirs."}, {"topic": "Plomb et exposition", "pages": [46], "id": "q13", "prompt": "Comment nomme-t-on l’intoxication par le plomb ?", "options": ["Le saturnisme", "La silicose", "L’asbestose", "La légionellose"], "correct": [0], "explanation": "L’intoxication au plomb est le saturnisme. Les voies citées sont l’ingestion et l’inhalation."}, {"topic": "Plomb et exposition", "pages": [47], "id": "q14", "prompt": "Quel indicateur mesure le plomb présent dans le sang ?", "options": ["La plombémie", "La glycémie", "La spirométrie", "La radiométrie du mur"], "correct": [0], "explanation": "C’est le taux de plomb dans le sang. C’est l’indicateur de référence cité pour dépister une contamination."}, {"topic": "Plomb et exposition", "pages": [47], "id": "q15", "prompt": "Où le plomb peut-il être stocké durablement dans l’organisme ?", "options": ["Dans les os", "Uniquement à la surface de la peau", "Exclusivement dans les cheveux", "Seulement dans l’air des poumons"], "correct": [0], "explanation": "Le plomb se stocke notamment dans les os. Il peut être relargué dans le sang des années plus tard, notamment pendant une grossesse."}, {"topic": "Plomb et exposition", "pages": [48], "id": "q16", "prompt": "Quelle population enfantine est particulièrement vulnérable selon le cours ?", "options": ["Les enfants de moins de 6 ans", "Uniquement les adolescents de plus de 16 ans", "Uniquement les nourrissons après 12 mois", "Seulement les enfants pratiquant un sport"], "correct": [0], "explanation": "Le comportement main-bouche et les jeux au sol favorisent l’ingestion de poussières et d’écailles. L’absorption digestive et la vulnérabilité du cerveau en développement sont plus importantes."}, {"topic": "Plomb et exposition", "pages": [48], "id": "q17", "prompt": "Que désigne le comportement de PICA évoqué dans le cours ?", "options": ["L’ingestion de matières non alimentaires", "Une méthode de mesure XRF", "Une fissure structurelle", "Un revêtement antirouille"], "correct": [0], "explanation": "Il s’agit de l’ingestion de matières non alimentaires. Exemple : terre ou écailles de peinture pouvant contenir du plomb."}, {"topic": "Prévention", "pages": [53], "id": "q18", "prompt": "Quel nettoyage est à éviter en présence de poussières de plomb ?", "options": ["Le balayage à sec", "Le nettoyage humide adapté", "L’aspiration à très haute efficacité adaptée", "L’essuyage humide des surfaces"], "correct": [0], "explanation": "Ils peuvent remettre en suspension ou disperser les poussières. Privilégier des méthodes adaptées : aspiration à très haute efficacité et nettoyage humide."}, {"topic": "Prévention", "pages": [64], "id": "q19", "prompt": "Sur quoi doit reposer la préparation d’un chantier exposant au plomb ?", "options": ["Une connaissance précise du risque dans le périmètre des travaux", "La seule couleur du mur", "L’âge de l’opérateur", "Une estimation sans visite ni diagnostic"], "correct": [0], "explanation": "La présence de plomb, les teneurs et l’état des surfaces, pièce par pièce et élément par élément. Ces données permettent une analyse des risques et le choix d’une technique limitant la pollution."}, {"topic": "Prévention", "pages": [65], "id": "q20", "prompt": "Où doit être situé le réfectoire du chantier ?", "options": ["Hors de la zone des travaux", "Dans la zone de ponçage", "Dans le local à déchets contaminés", "Contre les surfaces en cours de décapage"], "correct": [0], "explanation": "Un point d’eau avec savon, une douche ou des vestiaires séparant tenues de ville et de travail. Un second aménagement pertinent, dont le réfectoire situé hors de la zone des travaux."}, {"topic": "Prévention", "pages": [66], "id": "q21", "prompt": "Quel est le but de l’isolement d’une zone contaminée ?", "options": ["Éviter la dissémination des poussières", "Accélérer leur propagation", "Remplacer tous les EPI sans évaluation", "Masquer l’absence de diagnostic"], "correct": [0], "explanation": "La délimitation et la signalisation contrôlent l’accès à la zone à risque. L’isolement empêche la dissémination et protège les personnes des autres zones."}, {"topic": "Prévention", "pages": [67], "id": "q22", "prompt": "Où faut-il capter les poussières pendant une intervention ?", "options": ["Au plus près de leur source d’émission", "Uniquement à la sortie du bâtiment", "Après leur dispersion dans le quartier", "Seulement dans le véhicule"], "correct": [0], "explanation": "Captage à la source avec aspiration à très haute efficacité. Brumisation quand elle est possible, aspiration des copeaux ou nettoyage humide régulier."}, {"topic": "Prévention", "pages": [68], "id": "q23", "prompt": "Quelle pratique est expressément proscrite dans le support ?", "options": ["Le décapage au chalumeau", "Le captage des poussières", "Le nettoyage humide", "Le balisage de la zone"], "correct": [0], "explanation": "Ne pas décaper au chalumeau ni brûler du bois peint au plomb. Ne pas balayer la zone de travail ; deux pratiques distinctes correctement citées donnent le total."}, {"topic": "Prévention", "pages": [69], "id": "q24", "prompt": "Quel ordre de nettoyage final est décrit ?", "options": ["Aspiration à très haute efficacité puis essuyage humide", "Balayage puis soufflage à l’air comprimé", "Soufflage puis nettoyage des seuls outils", "Peinture immédiate sur les poussières"], "correct": [0], "explanation": "Nettoyer les zones de travaux et les accès par aspiration à très haute efficacité. Compléter par un essuyage humide et un nettoyage final après retrait des protections selon le protocole."}, {"topic": "Prévention", "pages": [72], "id": "q25", "prompt": "Quel type de filtre est cité pour protéger des poussières de plomb ?", "options": ["P3", "Un filtre à café", "Un filtre à eau domestique", "Un filtre sans classement"], "correct": [0], "explanation": "Ne pas boire, manger ni fumer dans la zone exposée. Se laver mains et visage avant les repas, prendre une douche et changer de vêtements après le travail."}, {"topic": "Cadre de mission", "pages": [81], "id": "q26", "prompt": "Quelle date de construction déclenche le champ du CREP vente décrit dans le cours ?", "options": ["Avant le 1er janvier 1949", "Après le 1er janvier 2010", "Seulement entre 1975 et 2000", "Avant le 1er janvier 1900 uniquement"], "correct": [0], "explanation": "Le cours vise les immeubles d’habitation construits avant le 1er janvier 1949. Pour un appartement en immeuble collectif, le CREP vente porte sur les parties privatives concernées."}, {"topic": "Cadre de mission", "pages": [81], "id": "q27", "prompt": "Pour une vente avec plomb au-dessus du seuil, quelle ancienneté du CREP est indiquée ?", "options": ["Moins d’un an", "Moins de six ans", "Moins de dix ans", "Aucune limite dans tous les cas"], "correct": [0], "explanation": "En présence de plomb au-dessus du seuil, le cours indique un constat établi depuis moins d’un an. Sans plomb ou avec concentrations inférieures au seuil, le constat initial peut être réutilisé."}, {"topic": "Cadre de mission", "pages": [82], "id": "q28", "prompt": "Qui supporte les frais du CREP en location ?", "options": ["Le bailleur", "Le locataire systématiquement", "L’entreprise de nettoyage", "Le voisin du logement"], "correct": [0], "explanation": "Le CREP est établi aux frais du bailleur. Il est annexé au nouveau contrat de location entrant dans le champ décrit par le cours."}, {"topic": "Cadre de mission", "pages": [83], "id": "q29", "prompt": "La réalisation du CREP des parties communes dépend-elle d’une vente ?", "options": ["Non, elle est indépendante de toute transaction", "Oui, toujours", "Seulement si tous les lots sont vendus", "Seulement à la demande d’un locataire"], "correct": [0], "explanation": "Il concerne les parties communes des immeubles collectifs d’habitation anciens visés, indépendamment d’une transaction. Le cours indique l’absence de durée de validité et la nécessité d’entretenir les revêtements."}, {"topic": "Cadre de mission", "pages": [84], "id": "q30", "prompt": "Face à des revêtements dégradés au plomb, quelle obligation est décrite ?", "options": ["Informer les occupants et réaliser les travaux appropriés", "Attendre obligatoirement la prochaine vente", "Informer seulement le voisin", "Effacer la mention du rapport"], "correct": [0], "explanation": "Informer les occupants et les personnes amenées à intervenir, notamment par remise du CREP. Réaliser les travaux appropriés pour supprimer le risque en garantissant la sécurité des occupants."}, {"topic": "Méthode CREP", "pages": [90], "id": "q31", "prompt": "Quelle suite d’étapes correspond au protocole présenté ?", "options": ["Préparation, visite et mesures, classement et rapport", "Rapport, vente, mesures éventuelles", "Mesures sans identification, puis oubli du croquis", "Travaux, démolition, demande du CREP"], "correct": [0], "explanation": "Préparer et identifier la mission et le bien, puis visiter et mesurer. Classer les unités de diagnostic et établir le rapport, ses conclusions et recommandations."}, {"topic": "Méthode CREP", "pages": [92], "id": "q32", "prompt": "Que faut-il faire pour un local non contrôlé ?", "options": ["Le mentionner et expliquer la raison", "Le supprimer du plan", "L’indiquer automatiquement sans plomb", "Le classer automatiquement 0"], "correct": [0], "explanation": "L’énumérer parmi les locaux non visités et indiquer la raison. Le faire apparaître sur le croquis avec une désignation claire, sans inventer de mesures."}, {"topic": "Méthode CREP", "pages": [98], "id": "q33", "prompt": "Comment désigner les locaux ?", "options": ["Par une appellation non équivoque et stable", "Uniquement par le prénom de l’occupant", "Par un nom différent à chaque page", "Par un numéro non reporté sur le plan"], "correct": [0], "explanation": "Les noms doivent être non ambigus et non susceptibles d’évoluer dans le temps. Le croquis doit être lisible et identifier les locaux ainsi que les zones."}, {"topic": "Méthode CREP", "pages": [100], "id": "q34", "prompt": "Un enduit peut-il être un revêtement à rechercher ?", "options": ["Oui, même s’il est relativement épais", "Non, seuls les liquides comptent", "Non, tous les enduits sont exempts de plomb", "Seulement s’il est bleu"], "correct": [0], "explanation": "Un revêtement est un matériau recouvrant un élément de construction ; le cours inclut les enduits même relativement épais. Exemples : peinture, vernis, enduit, feuille de plomb contrecollée, plomb laminé d’étanchéité."}, {"topic": "Méthode CREP", "pages": [100], "id": "q35", "prompt": "Pourquoi mesurer un mur recouvert de papier peint ?", "options": ["Une couche au plomb peut être masquée dessous", "Le papier peint est toujours du plomb pur", "Le papier peint remplace le substrat", "Toute mesure sur papier peint est interdite"], "correct": [0], "explanation": "Un matériau mince sans plomb peut recouvrir une couche plus ancienne contenant du plomb. Il faut donc prendre en compte les couches sous-jacentes et réaliser la recherche prévue."}, {"topic": "Méthode CREP", "pages": [101], "id": "q36", "prompt": "Qu’est-ce que le substrat ?", "options": ["Le matériau sur lequel le revêtement est appliqué", "La note finale de l’examen", "Une poussière prélevée au sol", "La seule couleur apparente"], "correct": [0], "explanation": "Le substrat est le support, par exemple bois, plâtre, brique ou métal. Le revêtement est la couche appliquée sur ce support, par exemple une peinture sur bois."}, {"topic": "Méthode CREP", "pages": [102], "id": "q37", "prompt": "Les faces intérieure et extérieure d’une fenêtre forment-elles une seule UD par principe ?", "options": ["Non, ce sont des UD distinctes", "Oui, toujours", "Oui, si la fenêtre est fermée", "Aucune n’entre dans le CREP"], "correct": [0], "explanation": "Les faces intérieure et extérieure ou appartenant à des locaux différents sont des UD distinctes. Elles peuvent avoir des historiques de revêtement différents."}, {"topic": "Méthode CREP", "pages": [103], "id": "q38", "prompt": "Comment découper une cage d’escalier en locaux ?", "options": ["Chaque palier et chaque partie entre deux paliers", "Une seule zone pour tout l’immeuble", "Une zone par couleur de peinture uniquement", "Aucun découpage n’est nécessaire"], "correct": [0], "explanation": "Chaque palier et chaque partie entre deux paliers constituent des locaux distincts. Exemples d’UD distinctes : marches, contremarches, balustres, main courante, limon, plafond."}, {"topic": "Méthode CREP", "pages": [104], "id": "q39", "prompt": "Quels critères définissent une unité de diagnostic ?", "options": ["Un même substrat et un même historique de construction et de revêtement a priori", "La seule proximité géographique", "La seule couleur actuelle", "Le même propriétaire dans tout l’immeuble"], "correct": [0], "explanation": "C’est un ou plusieurs éléments ayant a priori le même substrat. Ils ont aussi le même historique en matière de construction et de revêtement."}, {"topic": "Mesure et classement", "pages": [105], "id": "q40", "prompt": "Où réaliser une mesure sur une UD ?", "options": ["Sur une partie saine où la probabilité de présence est forte", "Uniquement sur un trou sans peinture", "Seulement sur le substrat mis à nu", "Sur l’étiquette de l’appareil"], "correct": [0], "explanation": "Rechercher les endroits où la probabilité de présence de plomb est forte, sur une partie saine. Si plusieurs mesures sont nécessaires, les réaliser à des endroits différents."}, {"topic": "Mesure et classement", "pages": [105], "id": "q41", "prompt": "Une première mesure conclusive à 2 mg/cm² impose combien de mesures au minimum sur cette UD ?", "options": ["Une seule", "Exactement deux dans tous les cas", "Exactement cinq", "Aucune"], "correct": [0], "explanation": "Une concentration supérieure ou égale à 1 mg/cm² met en évidence la présence au seuil. Une seule mesure suffit dans la stratégie décrite pour cette UD."}, {"topic": "Mesure et classement", "pages": [105], "id": "q42", "prompt": "Que faire après une première mesure conclusive inférieure à 1 mg/cm² ?", "options": ["Effectuer une deuxième mesure", "Conclure sans autre mesure dans tous les cas", "Classer automatiquement 3", "Effacer la première mesure"], "correct": [0], "explanation": "Effectuer une deuxième mesure sur un autre point de l’UD. Si les deux sont négatives mais une UD de même type dans le même local est positive, effectuer une troisième mesure."}, {"topic": "Mesure et classement", "pages": [107], "id": "q43", "prompt": "Quelle valeur retient-on après plusieurs mesures valides d’une UD ?", "options": ["La plus élevée, hors valeurs aberrantes", "La plus basse systématiquement", "La moyenne arrondie à zéro", "La dernière sans examiner les autres"], "correct": [0], "explanation": "Retenir la valeur la plus élevée en écartant les valeurs aberrantes. Répartir les mesures à des endroits différents pour limiter les faux négatifs."}, {"topic": "Mesure et classement", "pages": [107], "id": "q44", "prompt": "Que faire d’une mesure trop proche du seuil au regard de la précision ?", "options": ["La considérer non concluante et mesurer un autre point", "La transformer automatiquement en zéro", "Toujours la déclarer positive", "Supprimer l’UD du rapport"], "correct": [0], "explanation": "Comparer l’écart au seuil à la précision de l’appareil ; un écart inférieur rend la mesure non concluante selon le cours. Renouveler la mesure sur un autre point de l’UD."}, {"topic": "Mesure et classement", "pages": [108], "id": "q45", "prompt": "Jusqu’à quelle hauteur l’opérateur doit-il pouvoir mesurer selon le support ?", "options": ["3 mètres", "1 mètre", "1,5 mètre", "10 mètres sans préparation"], "correct": [0], "explanation": "Le diagnostiqueur doit pouvoir mesurer jusqu’à 3 m. Au-delà, prévoir des dispositions particulières avec le commanditaire dans le respect des règles de travail."}, {"topic": "Mesure et classement", "pages": [110], "id": "q46", "prompt": "Comment noter une fenêtre PVC manifestement sans revêtement non mesurée ?", "options": ["NM, sans classement 0 à 3", "Classe 0 automatiquement", "Classe 3 automatiquement", "Positive par défaut"], "correct": [0], "explanation": "NM signifie non mesurée, avec la raison de l’absence de mesure. Une classe 0 suppose une UD mesurée dont la concentration est inférieure au seuil ; les NM ne sont pas classées."}, {"topic": "Laboratoire", "pages": [111], "id": "q47", "prompt": "Quelle masse minimale de prélèvement est indiquée ?", "options": ["0,5 g", "0,5 mg", "5 kg", "50 g"], "correct": [0], "explanation": "Prélever au moins 0,5 g pour permettre l’analyse. Inclure l’ensemble des couches de peinture, y compris la plus profonde."}, {"topic": "Laboratoire", "pages": [111], "id": "q48", "prompt": "Pourquoi éviter le substrat dans le prélèvement de peinture ?", "options": ["Il peut diluer la concentration mesurée", "Il augmente toujours le plomb à l’infini", "Il rend le prélèvement non destructif", "Il remplace la peinture à analyser"], "correct": [0], "explanation": "Éviter substrat et corps étrangers pour ne pas diluer la concentration. Limiter la dissémination des poussières en prélevant toutes les couches de peinture."}, {"topic": "Laboratoire", "pages": [41], "id": "q49", "prompt": "Dans quelle unité exprime-t-on le plomb acido-soluble ?", "options": ["mg/g", "mg/cm²", "mètres", "Becquerels par pièce"], "correct": [0], "explanation": "La XRF donne une concentration surfacique en mg/cm². L’analyse acido-soluble donne une concentration massique en mg/g."}, {"topic": "Laboratoire", "pages": [111], "id": "q50", "prompt": "Que simule l’extraction acido-soluble ?", "options": ["La solubilisation dans le suc gastrique", "L’exposition au vent", "La résistance au feu", "La conduction électrique d’un mur"], "correct": [0], "explanation": "Il simule la solubilisation du plomb dans l’estomac. Le prélèvement dégrade la surface, ce qui justifie son caractère exceptionnel."}, {"topic": "Mesure et classement", "pages": [113], "id": "q51", "prompt": "Une couche au plomb masquée par un papier peint sans plomb est qualifiée de…", "options": ["Non visible", "Nécessairement dégradée", "Toujours absente", "Non mesurable dans tous les cas"], "correct": [0], "explanation": "Non visible : la couche au plomb est sous un revêtement sans plomb. Non dégradé : le revêtement visible ne présente pas les dégradations considérées."}, {"topic": "Mesure et classement", "pages": [113], "id": "q52", "prompt": "Quel état correspond à une usure ne générant pas spontanément de poussières ou d’écailles ?", "options": ["État d’usage", "Dégradé dans tous les cas", "Absence de revêtement", "Non visible dans tous les cas"], "correct": [0], "explanation": "L’état d’usage correspond aux dégradations courantes ne générant pas spontanément de poussières ou écailles. L’état dégradé correspond à des altérations générant de telles particules, notamment pulvérulence, écaillage ou cloquage."}, {"topic": "Mesure et classement", "pages": [114], "id": "q53", "prompt": "À quelle classe correspond une UD positive avec revêtement dégradé ?", "options": ["Classe 3", "Classe 0", "Classe 1", "Classe 2"], "correct": [0], "explanation": "Classe 0 : sous le seuil ; classe 1 : au seuil ou au-dessus, non visible ou non dégradé. Classe 2 : au seuil ou au-dessus, état d’usage ; classe 3 : au seuil ou au-dessus, dégradé."}, {"topic": "Rapport", "pages": [94], "id": "q54", "prompt": "Quelle information figure dans le tableau des mesures ?", "options": ["Le local, la zone et le libellé de l’UD", "Seulement le prénom du propriétaire", "Uniquement une moyenne générale", "Uniquement la date de vente"], "correct": [0], "explanation": "Deux informations parmi local, zone, libellé de l’UD, substrat, revêtement, localisation de la mesure. Deux autres parmi mesure ou raison de non-mesure, état, dégradation, classement, observations."}, {"topic": "Rapport", "pages": [96], "id": "q55", "prompt": "Quel élément d’identification de l’auteur figure en première page ?", "options": ["Sa signature et les références de son assurance", "Son mot de passe", "Son numéro de carte bancaire", "Son diplôme scolaire primaire"], "correct": [0], "explanation": "Deux parmi coordonnées propriétaire/commanditaire, auteur et signature, références d’assurance. Deux autres parmi dates, objet, circonstances et champ, occupation, identification de l’appareil utilisé."}, {"topic": "Radioprotection", "pages": [124], "id": "q56", "prompt": "Sur quel phénomène repose la XRF ?", "options": ["L’émission secondaire de rayons X par la matière excitée", "L’évaporation de la peinture", "La mesure de la seule couleur", "Une pesée du mur entier"], "correct": [0], "explanation": "La matière excitée par des rayons X réémet notamment des rayons X. Le spectre caractéristique permet d’identifier les éléments et d’en déduire leur teneur."}, {"topic": "Radioprotection", "pages": [129], "id": "q57", "prompt": "Où un risque existe-t-il lors d’une mesure à travers une cloison ?", "options": ["De l’autre côté, notamment dans l’axe du faisceau", "Uniquement au bureau administratif", "Exclusivement au sol à 100 mètres", "Nulle part si la peinture est récente"], "correct": [0], "explanation": "Des personnes peuvent se trouver de l’autre côté de la paroi, dans l’axe du faisceau. Le risque dépend de la nature, de l’épaisseur de la paroi et de la distance ; empêcher leur présence dans la zone concernée."}, {"topic": "Radioprotection", "pages": [134], "id": "q58", "prompt": "Comment tenir un échantillon pendant le tir ?", "options": ["Ne jamais le tenir avec les doigts", "Entre deux doigts devant l’appareil", "Sur la paume de la main", "Contre le corps sous une veste"], "correct": [0], "explanation": "Ne jamais orienter l’appareil vers soi ou quelqu’un, ni tenir l’échantillon avec les doigts. Se tenir derrière l’appareil, le maintenir éloigné du corps et éviter la partie avant."}, {"topic": "Radioprotection", "pages": [138], "id": "q59", "prompt": "Que signifie le principe d’optimisation ALARA ?", "options": ["Réduire l’exposition autant que raisonnablement possible", "Augmenter la dose pour aller plus vite", "Supprimer toute formation", "Mesurer sans contrôle d’accès"], "correct": [0], "explanation": "Justification : l’exposition doit être nécessaire et apporter un bénéfice ; optimisation : doses aussi basses que raisonnablement possible. Limitation : respecter les limites de dose applicables."}, {"topic": "Radioprotection", "pages": [138], "id": "q60", "prompt": "Un tube générateur de rayons X hors tension émet-il comme une source radioactive ?", "options": ["Non, il n’a pas de source radioactive et n’émet pas hors tension", "Oui, de la même manière en permanence", "Oui, uniquement pendant la nuit", "Il contient toujours du cobalt-57"], "correct": [0], "explanation": "Un tube X ne contient pas de source radioactive et n’émet pas de rayons X hors tension. Un appareil à source scellée peut émettre un rayonnement résiduel, même obturateur fermé, selon le cours."}, {"id": "qm0", "topic": "Plomb et exposition", "pages": [46], "prompt": "Quelles voies d’entrée du plomb dans l’organisme sont citées ?", "options": ["Ingestion", "Inhalation", "Simple observation à distance", "Écoute d’un bruit"], "correct": [0, 1], "explanation": "Le support identifie l’ingestion et l’inhalation de plomb."}, {"id": "qm1", "topic": "Méthode CREP", "pages": [102], "prompt": "Quels éléments constituent des UD distinctes ?", "options": ["Deux murs différents d’une même pièce", "Les faces intérieure et extérieure d’une fenêtre", "Une allège et sa paroi murale", "Toutes les plinthes de même historique d’un seul local, obligatoirement séparées"], "correct": [0, 1, 2], "explanation": "Le cours distingue les murs, les faces et les allèges ; les plinthes homogènes d’un local peuvent former une seule UD."}, {"id": "qm2", "topic": "Prévention", "pages": [68], "prompt": "Quelles pratiques sont proscrites sur un chantier de peintures au plomb ?", "options": ["Brûler le bois peint", "Décaper au chalumeau", "Balayer à sec", "Aspirer avec un matériel à très haute efficacité adapté"], "correct": [0, 1, 2], "explanation": "Le brûlage, le chalumeau et le balayage sont proscrits dans le support."}, {"id": "qm3", "topic": "Mesure et classement", "pages": [114], "prompt": "Quels états d’une UD au-dessus du seuil conduisent à la classe 1 ?", "options": ["Non visible", "Non dégradé", "État d’usage", "Dégradé"], "correct": [0, 1], "explanation": "Au seuil ou au-dessus : NV et ND donnent 1, EU donne 2, D donne 3."}, {"id": "qm4", "topic": "Radioprotection", "pages": [138], "prompt": "Quels sont les principes de radioprotection cités ?", "options": ["Justification", "Optimisation", "Limitation", "Exposition maximale systématique"], "correct": [0, 1, 2], "explanation": "Le cours présente justification, optimisation ALARA et limitation."}, {"id": "qm5", "topic": "Méthode CREP", "pages": [100], "prompt": "Quels revêtements sont susceptibles de contenir du plomb dans le périmètre décrit ?", "options": ["Peintures anciennes", "Vernis", "Enduits", "Carrelages à analyser systématiquement au titre de ce protocole"], "correct": [0, 1, 2], "explanation": "Peintures, vernis et enduits sont considérés. Les carrelages ne sont pas visés par ce protocole du cours."}], "practical": [{"id": "p1", "topic": "Mesure et classement", "pages": [113, 114], "title": "Plinthe du séjour", "context": "Plinthe en bois. Valeur XRF retenue : 2.4 mg/cm², conclusive. La peinture est intacte.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [1], "explanation": "Non dégradé : classe 1. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p2", "topic": "Mesure et classement", "pages": [113, 114], "title": "Porte du couloir", "context": "Porte peinte. Valeur XRF retenue : 3.2 mg/cm², conclusive. Une usure par friction ne produit ni poussières ni écailles spontanées.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [2], "explanation": "État d’usage : classe 2. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p3", "topic": "Mesure et classement", "pages": [113, 114], "title": "Mur de cuisine", "context": "Mur enduit. Valeur XRF retenue : 4.1 mg/cm², conclusive. La peinture s’écaille et les fragments tombent spontanément.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [3], "explanation": "Dégradé : classe 3. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p4", "topic": "Mesure et classement", "pages": [113, 114], "title": "Chambre sous papier peint", "context": "Mur peint. Valeur XRF retenue : 2.7 mg/cm², conclusive. La couche au plomb est manifestement masquée par un papier peint sans plomb.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [1], "explanation": "Non visible : classe 1. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p5", "topic": "Mesure et classement", "pages": [113, 114], "title": "Allège abîmée", "context": "Allège peinte. Valeur XRF retenue : 0.3 mg/cm², conclusive. Le revêtement présente un écaillage important. Toutes les mesures requises sont sous le seuil.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [0], "explanation": "Sous le seuil : classe 0. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p6", "topic": "Mesure et classement", "pages": [113, 114], "title": "Main courante", "context": "Main courante en bois. Valeur XRF retenue : 1.8 mg/cm², conclusive. Des traces de chocs d’usage ne génèrent pas spontanément de particules.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [2], "explanation": "État d’usage : classe 2. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p7", "topic": "Mesure et classement", "pages": [113, 114], "title": "Mur poudreux", "context": "Mur enduit. Valeur XRF retenue : 5.6 mg/cm², conclusive. La peinture se réduit facilement en poudre.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [3], "explanation": "Dégradé : classe 3. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p8", "topic": "Mesure et classement", "pages": [113, 114], "title": "Huisserie du bureau", "context": "Huisserie en bois. Valeur XRF retenue : 0.2 mg/cm², conclusive. La peinture est intacte. Toutes les mesures requises sont sous le seuil.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [0], "explanation": "Sous le seuil : classe 0. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p9", "topic": "Mesure et classement", "pages": [113, 114], "title": "Plafond cloqué", "context": "Plafond peint. Valeur XRF retenue : 2.9 mg/cm², conclusive. Le cloquage provoque une émission spontanée d’écailles.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [3], "explanation": "Dégradé : classe 3. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p10", "topic": "Mesure et classement", "pages": [113, 114], "title": "Fenêtre repeinte", "context": "Face intérieure de fenêtre. Valeur XRF retenue : 1.6 mg/cm², conclusive. Le revêtement visible est intact.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [1], "explanation": "Non dégradé : classe 1. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p11", "topic": "Mesure et classement", "pages": [113, 114], "title": "Contremarches", "context": "Contremarches peintes. Valeur XRF retenue : 3.8 mg/cm², conclusive. Des microfissures d’usage ne libèrent pas de particules spontanées.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [2], "explanation": "État d’usage : classe 2. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p12", "topic": "Mesure et classement", "pages": [113, 114], "title": "Mur sous toile", "context": "Mur peint. Valeur XRF retenue : 4.5 mg/cm², conclusive. La peinture au plomb est manifestement sous une toile de verre sans plomb.", "prompt": "Quel classement retenir pour cette UD ?", "options": ["Classe 0", "Classe 1", "Classe 2", "Classe 3"], "correct": [1], "explanation": "Non visible : classe 1. Sous 1 mg/cm², la classe est 0 ; au seuil ou au-dessus, NV/ND = 1, EU = 2, D = 3."}, {"id": "p13", "topic": "Mesure et classement", "pages": [105], "title": "Premier point positif", "context": "Sur une porte, la première mesure conclusive donne 2,2 mg/cm².", "prompt": "Combien de mesures supplémentaires impose cette stratégie sur cette UD ?", "options": ["Aucune", "Une systématiquement", "Deux systématiquement", "Quatre"], "correct": [0], "explanation": "La première mesure conclusive est supérieure au seuil : une seule suffit."}, {"id": "p14", "topic": "Mesure et classement", "pages": [105], "title": "Premier point négatif", "context": "Sur un mur peint, la première mesure conclusive donne 0,2 mg/cm².", "prompt": "Quelle est l’étape suivante ?", "options": ["Réaliser une deuxième mesure à un autre endroit", "Conclure immédiatement classe 0", "Faire une moyenne avec une autre pièce", "Classer en NM"], "correct": [0], "explanation": "Après une première mesure sous le seuil, une seconde est nécessaire."}, {"id": "p15", "topic": "Mesure et classement", "pages": [105], "title": "Une troisième mesure ?", "context": "Deux mesures conclusives d’une porte sont sous le seuil. Dans le même local, une autre UD de même type est positive.", "prompt": "Que faire sur la première porte ?", "options": ["Réaliser une troisième mesure", "Arrêter après les deux mesures", "La classer automatiquement 3", "Reprendre la valeur de l’autre porte"], "correct": [0], "explanation": "Deux mesures négatives et une UD de même type positive dans le même local imposent une troisième mesure."}, {"id": "p16", "topic": "Mesure et classement", "pages": [105], "title": "Fin de série", "context": "Deux mesures conclusives sont sous le seuil. Aucune autre UD du même type n’est positive dans le local.", "prompt": "Quelle décision suit la stratégie décrite ?", "options": ["Arrêter les mesures de cette UD et retenir le résultat sous le seuil", "Faire toujours une troisième mesure", "Classer 3 par précaution", "Changer de local pour chercher une valeur à copier"], "correct": [0], "explanation": "La condition de troisième mesure n’est pas réunie."}, {"id": "p17", "topic": "Mesure et classement", "pages": [107], "title": "Choisir le résultat", "context": "Trois mesures valides, non aberrantes, d’une UD donnent 0,2 ; 0,4 ; 1,8 mg/cm².", "prompt": "Quelle valeur retenir ?", "options": ["1,8 mg/cm²", "0,2 mg/cm²", "0,8 mg/cm²", "0,4 mg/cm²"], "correct": [0], "explanation": "La valeur retenue est la plus élevée, hors valeurs aberrantes."}, {"id": "p18", "topic": "Mesure et classement", "pages": [107], "title": "Précision de l’appareil", "context": "La mesure vaut 0,95 mg/cm² et la précision annoncée est de 0,10 mg/cm².", "prompt": "Comment la traiter selon le cours ?", "options": ["Non concluante ; renouveler sur un autre point", "Négative certaine", "Positive certaine", "Remplacer par zéro"], "correct": [0], "explanation": "L’écart au seuil vaut 0,05, inférieur à 0,10 : la mesure est non concluante."}, {"id": "p19", "topic": "Mesure et classement", "pages": [107], "title": "Répartir les points", "context": "Une deuxième mesure est nécessaire sur une paroi murale.", "prompt": "Où la réaliser ?", "options": ["À un autre endroit, par exemple en partie basse si la première était en haut", "Exactement sur le premier point", "Sur une autre UD seulement", "Sur le boîtier de l’appareil"], "correct": [0], "explanation": "Les mesures d’une même UD sont réalisées en des endroits différents."}, {"id": "p20", "topic": "Mesure et classement", "pages": [105], "title": "Peinture écaillée", "context": "Une porte comporte une zone saine et un trou où le support est mis à nu.", "prompt": "Où privilégier la mesure du revêtement ?", "options": ["Sur une partie saine représentative où la présence de plomb est probable", "Au centre du trou sans peinture", "Dans l’air devant la porte", "Sur une vis du trépied"], "correct": [0], "explanation": "Le protocole prévoit une mesure sur une partie saine de l’UD."}, {"id": "p21", "topic": "Méthode CREP", "pages": [110, 114], "title": "Fenêtre PVC", "context": "Une fenêtre PVC manifestement sans revêtement n’a pas été mesurée.", "prompt": "Quelle inscription est cohérente ?", "options": ["NM avec motif, sans classe 0 à 3", "Classe 0 prouvant une mesure négative", "Classe 1 car récente", "Classe 3 car non mesurée"], "correct": [0], "explanation": "Une UD non mesurée n’est pas classée ; le motif est mentionné."}, {"id": "p22", "topic": "Méthode CREP", "pages": [100, 101], "title": "Papier peint neuf", "context": "Un papier peint sans plomb a été posé sur un mur ancien dont les couches sous-jacentes sont inconnues.", "prompt": "Que faire ?", "options": ["Rechercher le plomb dans les couches sous-jacentes selon le protocole", "Exclure le mur parce que le papier est neuf", "Déclarer le mur automatiquement positif", "Mesurer seulement la colle hors du mur"], "correct": [0], "explanation": "Un matériau mince peut masquer une ancienne couche au plomb."}, {"id": "p23", "topic": "Méthode CREP", "pages": [100, 110], "title": "Faïence murale", "context": "Une surface est recouverte de faïence, cas d’exclusion décrit dans le cours.", "prompt": "Comment la traiter dans ce CREP ?", "options": ["La repérer comme non mesurée avec le motif", "Lui attribuer automatiquement la classe 3", "Mesurer systématiquement chaque carreau", "La déclarer négative après simple observation"], "correct": [0], "explanation": "Le cours exclut carrelages et faïences de cette recherche ; NM n’est pas un résultat négatif mesuré."}, {"id": "p24", "topic": "Méthode CREP", "pages": [102], "title": "Deux faces d’une porte", "context": "Une porte sépare une cuisine d’un couloir. Ses deux faces ont pu être peintes différemment.", "prompt": "Comment définir les UD ?", "options": ["Une UD distincte par face dans son local", "Une seule UD pour les deux locaux", "Une seule UD pour toutes les portes du logement", "Aucune UD car la porte est mobile"], "correct": [0], "explanation": "Les éléments situés dans des locaux différents sont distincts."}, {"id": "p25", "topic": "Méthode CREP", "pages": [102], "title": "Mur à pan de bois", "context": "Une paroi associe un pan de bois peint et une surface plâtrée peinte.", "prompt": "Comment découper les UD ?", "options": ["Distinguer les substrats bois et plâtre", "Regrouper uniquement parce que la couleur est identique", "Mesurer seulement le bois et oublier le plâtre", "Ne rien mesurer"], "correct": [0], "explanation": "Les substrats différents constituent des UD distinctes."}, {"id": "p26", "topic": "Méthode CREP", "pages": [102], "title": "Plinthes homogènes", "context": "Dans un même local, les plinthes ont le même substrat et le même historique de revêtement.", "prompt": "Quel regroupement est possible ?", "options": ["Une UD pour cet ensemble de plinthes", "Une UD comprenant toutes les plinthes de l’immeuble", "Une UD commune avec les murs de substrat différent", "Aucun regroupement n’est jamais possible"], "correct": [0], "explanation": "L’ensemble des plinthes homogènes d’un même local peut constituer une UD."}, {"id": "p27", "topic": "Méthode CREP", "pages": [102], "title": "Allège et mur", "context": "Dans un séjour, vous identifiez une allège et la paroi murale à laquelle elle appartient.", "prompt": "Quelle organisation est indiquée ?", "options": ["Deux UD distinctes", "Une seule UD obligatoire", "Exclure systématiquement l’allège", "Exclure systématiquement le mur"], "correct": [0], "explanation": "Le support distingue l’allège ou l’embrasure de la paroi murale."}, {"id": "p28", "topic": "Méthode CREP", "pages": [103], "title": "Escalier collectif", "context": "Vous devez repérer une cage d’escalier comprenant plusieurs paliers et volées.", "prompt": "Quel découpage choisir ?", "options": ["Un local pour chaque palier et chaque partie entre deux paliers", "Un seul local pour toutes les volées et tous les paliers", "Un local uniquement pour les marches abîmées", "Aucun local pour les circulations"], "correct": [0], "explanation": "Le découpage distingue les paliers et les parties de cage entre paliers."}, {"id": "p29", "topic": "Méthode CREP", "pages": [103], "title": "Marche et contremarche", "context": "Dans une même partie de cage d’escalier, marches et contremarches sont peintes.", "prompt": "Quelle organisation retenir ?", "options": ["Une UD pour l’ensemble des marches et une autre pour les contremarches", "Tout fusionner obligatoirement avec la main courante", "Mesurer uniquement le plafond", "Exclure les marches du CREP"], "correct": [0], "explanation": "Les ensembles de marches et de contremarches sont des UD distinctes."}, {"id": "p30", "topic": "Méthode CREP", "pages": [98], "title": "Placard verrouillé", "context": "Un placard faisant partie du bien est inaccessible lors de la visite.", "prompt": "Que devez-vous faire ?", "options": ["Le lister, justifier la non-visite et le repérer sur le croquis", "Le supprimer du rapport", "Inventer des mesures par analogie", "Le classer 0 sans mesure"], "correct": [0], "explanation": "Tous les locaux, visités ou non, sont repérés ; l’absence de visite est motivée."}, {"id": "p31", "topic": "Méthode CREP", "pages": [101], "title": "Deux fenêtres", "context": "Deux fenêtres se trouvent dans la même zone du séjour.", "prompt": "Comment éviter toute ambiguïté ?", "options": ["Identifier séparément chacune et la repérer sur le croquis", "Les nommer toutes deux « fenêtre » sans distinction", "Reporter seulement leur couleur", "Conserver une seule ligne au hasard"], "correct": [0], "explanation": "Plusieurs UD de même type dans une zone doivent être clairement identifiées."}, {"id": "p32", "topic": "Méthode CREP", "pages": [108], "title": "Revêtement à 4 mètres", "context": "Une UD se trouve à 4 m de hauteur.", "prompt": "Quelle préparation est prévue ?", "options": ["Convenir de dispositions particulières adaptées avec le commanditaire", "Monter sur un meuble instable", "Déclarer automatiquement classe 0", "L’ignorer sans mention"], "correct": [0], "explanation": "Au-delà de 3 m, des dispositions particulières doivent être prévues dans le respect des règles de travail."}, {"id": "p33", "topic": "Laboratoire", "pages": [111], "title": "Échantillon trop petit", "context": "Un prélèvement de peinture pèse 0,2 g.", "prompt": "Est-il suffisant au regard du minimum indiqué ?", "options": ["Non, il faut au moins 0,5 g", "Oui, le minimum est 0,05 g", "Oui, toute écaille suffit", "Non, il faut 5 kg"], "correct": [0], "explanation": "Le cours indique un prélèvement minimal de 0,5 g."}, {"id": "p34", "topic": "Laboratoire", "pages": [111], "title": "Couche profonde", "context": "Un prélèvement contient seulement la peinture de surface, alors que plusieurs couches sont visibles.", "prompt": "Que corriger ?", "options": ["Inclure toutes les couches, jusqu’à la plus profonde", "Ne garder que la couche récente", "Ajouter du plâtre pour augmenter la masse", "Ajouter de l’eau pour atteindre le poids"], "correct": [0], "explanation": "L’ensemble des couches de peinture doit être prélevé."}, {"id": "p35", "topic": "Laboratoire", "pages": [111], "title": "Substrat dans le sachet", "context": "Des morceaux de plâtre se mélangent aux écailles prélevées.", "prompt": "Quel problème faut-il éviter ?", "options": ["La dilution de la concentration par le substrat", "La transformation du plomb en fer", "Une multiplication certaine du résultat par dix", "La suppression de tous les risques"], "correct": [0], "explanation": "Le substrat et les corps étrangers risquent de diluer la concentration de l’échantillon."}, {"id": "p36", "topic": "Laboratoire", "pages": [41], "title": "Lecture du laboratoire", "context": "Un rapport donne le plomb acido-soluble en mg/g.", "prompt": "À quel type de grandeur correspond ce résultat ?", "options": ["Une concentration massique", "Une concentration surfacique XRF", "Une longueur de prélèvement", "Une activité radioactive"], "correct": [0], "explanation": "Les mg/g sont une masse de plomb par masse d’échantillon."}, {"id": "p37", "topic": "Laboratoire", "pages": [41], "title": "Calcul de concentration", "context": "Pour l’exercice, c = 8 mg/L, V = 0,025 L et M = 0,10 g. Utilisez C = c × V / M.", "prompt": "Quelle concentration obtenez-vous ?", "options": ["2 mg/g", "0,02 mg/g", "20 mg/cm²", "0,2 mg/g"], "correct": [0], "explanation": "8 × 0,025 ÷ 0,10 = 2 mg/g. Ne pas confondre avec les mg/cm²."}, {"id": "p38", "topic": "Rapport", "pages": [94], "title": "Résultat impossible à localiser", "context": "Le tableau ne comporte que des concentrations, sans local ni zone.", "prompt": "Quelle correction est nécessaire ?", "options": ["Relier chaque mesure au local, à la zone et à l’UD", "Conserver seulement une moyenne générale", "Supprimer les résultats positifs", "Remplacer toutes les zones par « divers »"], "correct": [0], "explanation": "La traçabilité exige le local, la zone, l’UD et les autres données du tableau."}, {"id": "p39", "topic": "Rapport", "pages": [96], "title": "Rapport non signé", "context": "Le rapport comporte les résultats mais ne porte pas la signature de l’auteur.", "prompt": "Que compléter ?", "options": ["L’identification de l’auteur et sa signature", "Le mot de passe de l’appareil", "Le numéro bancaire du propriétaire", "Le prénom du voisin"], "correct": [0], "explanation": "La première page doit identifier l’auteur et porter sa signature selon le support."}, {"id": "p40", "topic": "Cadre de mission", "pages": [81], "title": "Vente d’un appartement de 1930", "context": "La mission est le CREP de vente des parties privatives d’un appartement.", "prompt": "Quel périmètre correspond à cette mission ?", "options": ["Les parties privatives d’habitation concernées", "Uniquement la façade de l’immeuble", "Seulement la cage d’escalier commune", "Tous les appartements des voisins"], "correct": [0], "explanation": "Le CREP vente d’un lot d’habitation porte sur ses parties privatives."}, {"id": "p41", "topic": "Cadre de mission", "pages": [81], "title": "Ancien constat positif", "context": "Pour une vente, un CREP positif au-dessus du seuil a été établi il y a 18 mois.", "prompt": "Satisfait-il à l’ancienneté indiquée dans le cours ?", "options": ["Non, le cours demande moins d’un an", "Oui, la limite est toujours six ans", "Oui, un résultat positif est illimité", "Oui, si la couleur n’a pas changé"], "correct": [0], "explanation": "Pour cette situation, le cours indique un CREP de moins d’un an."}, {"id": "p42", "topic": "Cadre de mission", "pages": [84], "title": "Travaux après diagnostic", "context": "Un CREP signale des revêtements dégradés au plomb. Une entreprise va intervenir.", "prompt": "Quelle action du propriétaire est attendue ?", "options": ["Informer les intervenants, notamment en leur remettant le CREP", "Cacher les résultats pour accélérer les travaux", "Informer uniquement la banque", "Attendre la fin des travaux pour transmettre"], "correct": [0], "explanation": "L’information des occupants et intervenants accompagne les travaux appropriés."}, {"id": "p43", "topic": "Prévention", "pages": [53], "title": "Chambre d’enfant", "context": "Des écailles de peinture ancienne sont accessibles à un jeune enfant.", "prompt": "Quelle mesure de protection est cohérente avec le support ?", "options": ["Empêcher l’accès aux peintures dégradées et éviter le contact des jouets", "Laisser l’enfant jouer avec les écailles", "Balayer à sec pendant sa présence", "Déplacer les écailles sous le lit"], "correct": [0], "explanation": "Le support demande de limiter l’accès aux revêtements dégradés et le contact des objets de l’enfant."}, {"id": "p44", "topic": "Prévention", "pages": [65, 69], "title": "Pause déjeuner", "context": "Un intervenant veut déjeuner dans la zone de travaux contaminée.", "prompt": "Que retenir ?", "options": ["Manger hors de la zone après les mesures d’hygiène", "Manger sur la zone en gardant les gants souillés", "Manger seulement près d’une fenêtre ouverte", "Une boisson suffit à éliminer le plomb"], "correct": [0], "explanation": "Le réfectoire est hors zone ; l’hygiène des mains et le retrait des équipements souillés sont nécessaires."}, {"id": "p45", "topic": "Prévention", "pages": [66], "title": "Poussières vers le couloir", "context": "Des poussières quittent la zone de travaux et atteignent une circulation occupée.", "prompt": "Quelle mesure collective manque ?", "options": ["Un isolement efficace et un contrôle des accès de la zone", "Une affiche publicitaire", "Une couleur de peinture plus foncée", "Un changement de propriétaire"], "correct": [0], "explanation": "L’isolement vise à empêcher la dissémination et à protéger les autres zones."}, {"id": "p46", "topic": "Prévention", "pages": [67], "title": "Poussières à l’outil", "context": "Une opération produit des poussières au point de travail.", "prompt": "Où mettre le captage ?", "options": ["Au plus près de la source d’émission", "Uniquement dans le parking", "Après dispersion dans toutes les pièces", "Dans le réfectoire"], "correct": [0], "explanation": "Le captage à la source réduit la dispersion."}, {"id": "p47", "topic": "Prévention", "pages": [68], "title": "Projet de décapage", "context": "Un intervenant propose de décaper une peinture au plomb au chalumeau.", "prompt": "Quelle décision correspond au support ?", "options": ["Écarter cette technique proscrite", "L’accepter si la flamme est petite", "L’accepter si la porte est ouverte", "L’imposer pour toutes les surfaces"], "correct": [0], "explanation": "Le décapage au chalumeau figure parmi les pratiques proscrites."}, {"id": "p48", "topic": "Prévention", "pages": [69], "title": "Fin de chantier", "context": "La zone est encore poussiéreuse après travaux.", "prompt": "Quelle méthode retenir ?", "options": ["Aspirateur à très haute efficacité puis essuyage humide", "Soufflette à air comprimé", "Balai sec puis départ", "Recouvrir les poussières sans nettoyage"], "correct": [0], "explanation": "Le support décrit aspiration adaptée puis nettoyage humide des zones et des accès."}, {"id": "p49", "topic": "Radioprotection", "pages": [133], "title": "Une personne derrière la cloison", "context": "Avant une mesure, vous constatez qu’un occupant se trouve dans le local attenant, dans l’axe possible du faisceau.", "prompt": "Quelle action préalable retenir ?", "options": ["Empêcher sa présence dans la zone concernée avant de mesurer", "Mesurer immédiatement", "Lui demander de fermer les yeux", "Augmenter la durée de mesure"], "correct": [0], "explanation": "Il faut s’assurer que personne ne soit exposé derrière la paroi et contrôler l’accès."}, {"id": "p50", "topic": "Radioprotection", "pages": [134], "title": "Échantillon dans la main", "context": "Un collègue propose de tenir un petit échantillon avec ses doigts devant l’appareil.", "prompt": "Que répondre ?", "options": ["Refuser : ne jamais tenir l’échantillon avec les doigts pendant le tir", "Accepter s’il porte des gants ordinaires", "Accepter pour moins d’une seconde", "Accepter si le résultat attendu est négatif"], "correct": [0], "explanation": "Les doigts ne doivent jamais servir de support à l’échantillon pendant une mesure."}, {"id": "p51", "topic": "Radioprotection", "pages": [134], "title": "Appareil sans surveillance", "context": "L’opérateur quitte la pièce et laisse l’appareil accessible à un occupant.", "prompt": "Quelle règle est enfreinte ?", "options": ["Ne pas laisser l’appareil sans surveillance", "Toujours laisser l’appareil au client", "Ne jamais ranger la valise", "Toujours prêter l’appareil au premier venu"], "correct": [0], "explanation": "Le support impose de garder la maîtrise de l’appareil et de le ranger après usage."}, {"id": "p52", "topic": "Radioprotection", "pages": [132], "title": "Panne de l’analyseur", "context": "L’analyseur présente une panne interne.", "prompt": "Quelle décision correspond au cours ?", "options": ["Confier l’intervention au fournisseur habilité", "Ouvrir soi-même le blindage", "Demander au client de remplacer la source", "Continuer en neutralisant une sécurité"], "correct": [0], "explanation": "Le support réserve la maintenance et le remplacement de la source au fournisseur habilité."}, {"id": "p53", "topic": "Radioprotection", "pages": [138], "title": "Tube X éteint", "context": "Le générateur électrique est hors tension et ne comporte pas de source radioactive.", "prompt": "Quelle affirmation est correcte ?", "options": ["Il ne produit pas de rayons X hors tension", "Il émet en permanence comme une source scellée", "Il devient radioactif par simple stockage", "Il contient nécessairement du cadmium-109"], "correct": [0], "explanation": "Le tube génère des rayons X lorsqu’il est activé, pas hors tension."}, {"id": "p54", "topic": "Radioprotection", "pages": [129], "title": "Source scellée au repos", "context": "Un appareil à source scellée est arrêté, obturateur fermé.", "prompt": "Quelle affirmation suit le cours ?", "options": ["Un rayonnement résiduel peut subsister", "Tout rayonnement disparaît nécessairement", "La source est détruite à chaque arrêt", "Le plomb du mur devient sa source d’énergie"], "correct": [0], "explanation": "Le cours décrit une émission résiduelle variable selon l’appareil et l’activité de sa source."}, {"id": "p55", "topic": "Prévention", "pages": [66, 67], "title": "Organiser une zone de travaux", "context": "Une intervention sur une peinture au plomb va produire des poussières.", "prompt": "Quelles mesures sont cohérentes ?", "options": ["Délimiter et signaler la zone", "Capter les émissions à la source", "Prévoir un isolement évitant la dispersion", "Utiliser un balai sec pour disperser les poussières"], "correct": [0, 1, 2], "explanation": "Balisage, isolement et captage sont complémentaires. Le balayage à sec est proscrit."}, {"id": "p56", "topic": "Méthode CREP", "pages": [92, 98], "title": "Préparer une visite", "context": "Vous préparez le relevé d’un appartement ancien dont une pièce restera inaccessible.", "prompt": "Quelles informations conserver ?", "options": ["La liste des locaux visités", "La pièce non visitée et son motif", "Un croquis identifiant aussi cette pièce", "Une concentration inventée pour la pièce inaccessible"], "correct": [0, 1, 2], "explanation": "Le rapport garde la trace des locaux visités et non visités, sans inventer de résultat."}, {"id": "p57", "topic": "Laboratoire", "pages": [111], "title": "Prélever proprement", "context": "Un prélèvement exceptionnel de peinture est justifié.", "prompt": "Quelles précautions retenir ?", "options": ["Prélever toutes les couches", "Éviter les corps étrangers et le substrat", "Limiter la dispersion des poussières", "Ajouter du plâtre pour atteindre la masse"], "correct": [0, 1, 2], "explanation": "Toutes les couches, sans substrat ni corps étrangers, et maîtrise des poussières ; minimum 0,5 g."}], "open": [{"topic": "Bâtiment", "pages": [3], "id": "o1", "prompt": "Expliquez le rôle de l’ossature et citez deux types de charges.", "rubric": ["Elle supporte les efforts du bâtiment.", "Exemples : poids propre, occupants et mobilier, neige ou sollicitations sismiques."]}, {"topic": "Bâtiment", "pages": [7], "id": "o2", "prompt": "Décrivez les planchers et les murs de refend des maisons 1900–1920.", "rubric": ["Les planchers sont fréquemment en solives de bois.", "La portée limitée des solives nécessite des murs de refend."]}, {"topic": "Bâtiment", "pages": [8], "id": "o3", "prompt": "Quels matériaux coexistent dans la construction de 1920 à 1945 ?", "rubric": ["La pierre et le bois restent employés.", "Ils coexistent avec le béton, le ciment, le métal ou les produits des filières industrielles locales."]}, {"topic": "Bâtiment", "pages": [9], "id": "o4", "prompt": "Décrivez deux évolutions constructives ou de confort de 1945 à 1975.", "rubric": ["Les matériaux industriels se généralisent et les procédés se normalisent.", "Le chauffage central se diffuse ; le béton prend une place importante."]}, {"topic": "Bâtiment", "pages": [14], "id": "o5", "prompt": "Distinguez fonds servant et fonds dominant.", "rubric": ["Le fonds servant supporte la contrainte.", "Le fonds dominant bénéficie de cette servitude, attachée au bien."]}, {"topic": "Plomb et exposition", "pages": [27], "id": "o6", "prompt": "Nommez le principal minerai du plomb et indiquez sa formule.", "rubric": ["Il s’agit de la galène.", "Sa formule est PbS."]}, {"topic": "Plomb et exposition", "pages": [28], "id": "o7", "prompt": "Citez deux propriétés physiques du plomb présentées dans le cours.", "rubric": ["Le plomb est malléable et facile à travailler.", "Sa forte densité ou son bas point de fusion est cité ; accepter aussi son aspect gris bleuâtre."]}, {"topic": "Plomb et exposition", "pages": [31], "id": "o8", "prompt": "Décrivez un fil à plomb et sa fonction.", "rubric": ["C’est un fil lesté.", "Il donne la direction de la pesanteur, donc la verticale."]}, {"topic": "Plomb et exposition", "pages": [32], "id": "o9", "prompt": "Définissez la céruse et citez un de ses usages historiques.", "rubric": ["C’est un pigment blanc à base de plomb.", "Il a été utilisé dans les peintures ou dans les fards et cosmétiques."]}, {"topic": "Plomb et exposition", "pages": [33], "id": "o10", "prompt": "Présentez le minium et le risque associé à son retrait.", "rubric": ["C’est un pigment au plomb, notamment utilisé comme antirouille.", "Le ponçage ou le brûlage peut libérer du plomb et provoquer une exposition toxique."]}, {"topic": "Plomb et exposition", "pages": [36], "id": "o11", "prompt": "Expliquez comment une peinture ancienne peut exposer les occupants au plomb.", "rubric": ["Une peinture à la céruse peut se dégrader, notamment avec l’humidité.", "Des écailles et poussières sont libérées puis ingérées ou inhalées."]}, {"topic": "Plomb et exposition", "pages": [37], "id": "o12", "prompt": "Citez deux sources domestiques de plomb autres que les peintures.", "rubric": ["Premier exemple pertinent : eau circulant dans des canalisations en plomb, poussières professionnelles ou industrielles.", "Second exemple distinct : céramiques artisanales, cosmétiques traditionnels, jouets au plomb ou certains loisirs."]}, {"topic": "Plomb et exposition", "pages": [46], "id": "o13", "prompt": "Nommez l’intoxication au plomb et les deux voies d’exposition citées.", "rubric": ["L’intoxication au plomb est le saturnisme.", "Les voies citées sont l’ingestion et l’inhalation."]}, {"topic": "Plomb et exposition", "pages": [47], "id": "o14", "prompt": "Définissez la plombémie et précisez son intérêt.", "rubric": ["C’est le taux de plomb dans le sang.", "C’est l’indicateur de référence cité pour dépister une contamination."]}, {"topic": "Plomb et exposition", "pages": [47], "id": "o15", "prompt": "Expliquez le stockage du plomb et sa possible remobilisation.", "rubric": ["Le plomb se stocke notamment dans les os.", "Il peut être relargué dans le sang des années plus tard, notamment pendant une grossesse."]}, {"topic": "Plomb et exposition", "pages": [48], "id": "o16", "prompt": "Pourquoi les jeunes enfants sont-ils particulièrement exposés au plomb ?", "rubric": ["Le comportement main-bouche et les jeux au sol favorisent l’ingestion de poussières et d’écailles.", "L’absorption digestive et la vulnérabilité du cerveau en développement sont plus importantes."]}, {"topic": "Plomb et exposition", "pages": [48], "id": "o17", "prompt": "Définissez le PICA et donnez un exemple pertinent dans un logement ancien.", "rubric": ["Il s’agit de l’ingestion de matières non alimentaires.", "Exemple : terre ou écailles de peinture pouvant contenir du plomb."]}, {"topic": "Prévention", "pages": [53], "id": "o18", "prompt": "Pourquoi éviter le balai et l’aspirateur ordinaire sur des poussières de plomb ?", "rubric": ["Ils peuvent remettre en suspension ou disperser les poussières.", "Privilégier des méthodes adaptées : aspiration à très haute efficacité et nettoyage humide."]}, {"topic": "Prévention", "pages": [64], "id": "o19", "prompt": "Que doit connaître l’entreprise avant de choisir son mode opératoire ?", "rubric": ["La présence de plomb, les teneurs et l’état des surfaces, pièce par pièce et élément par élément.", "Ces données permettent une analyse des risques et le choix d’une technique limitant la pollution."]}, {"topic": "Prévention", "pages": [65], "id": "o20", "prompt": "Citez deux aménagements d’hygiène prévus sur un chantier plomb.", "rubric": ["Un point d’eau avec savon, une douche ou des vestiaires séparant tenues de ville et de travail.", "Un second aménagement pertinent, dont le réfectoire situé hors de la zone des travaux."]}, {"topic": "Prévention", "pages": [66], "id": "o21", "prompt": "Expliquez le rôle du balisage et de l’isolement d’un chantier plomb.", "rubric": ["La délimitation et la signalisation contrôlent l’accès à la zone à risque.", "L’isolement empêche la dissémination et protège les personnes des autres zones."]}, {"topic": "Prévention", "pages": [67], "id": "o22", "prompt": "Donnez deux mesures qui réduisent les poussières pendant les travaux.", "rubric": ["Captage à la source avec aspiration à très haute efficacité.", "Brumisation quand elle est possible, aspiration des copeaux ou nettoyage humide régulier."]}, {"topic": "Prévention", "pages": [68], "id": "o23", "prompt": "Citez deux pratiques proscrites sur des revêtements au plomb.", "rubric": ["Ne pas décaper au chalumeau ni brûler du bois peint au plomb.", "Ne pas balayer la zone de travail ; deux pratiques distinctes correctement citées donnent le total."]}, {"topic": "Prévention", "pages": [69], "id": "o24", "prompt": "Décrivez le nettoyage de fin de chantier.", "rubric": ["Nettoyer les zones de travaux et les accès par aspiration à très haute efficacité.", "Compléter par un essuyage humide et un nettoyage final après retrait des protections selon le protocole."]}, {"topic": "Prévention", "pages": [72], "id": "o25", "prompt": "Donnez deux règles d’hygiène pour les salariés exposés au plomb.", "rubric": ["Ne pas boire, manger ni fumer dans la zone exposée.", "Se laver mains et visage avant les repas, prendre une douche et changer de vêtements après le travail."]}, {"topic": "Cadre de mission", "pages": [81], "id": "o26", "prompt": "Précisez le champ d’un CREP lors de la vente d’un appartement ancien.", "rubric": ["Le cours vise les immeubles d’habitation construits avant le 1er janvier 1949.", "Pour un appartement en immeuble collectif, le CREP vente porte sur les parties privatives concernées."]}, {"topic": "Cadre de mission", "pages": [81], "id": "o27", "prompt": "Comparez la validité en vente avec et sans plomb au seuil visé par le cours.", "rubric": ["En présence de plomb au-dessus du seuil, le cours indique un constat établi depuis moins d’un an.", "Sans plomb ou avec concentrations inférieures au seuil, le constat initial peut être réutilisé."]}, {"topic": "Cadre de mission", "pages": [82], "id": "o28", "prompt": "Pour la location, indiquez qui finance le CREP et où il est annexé.", "rubric": ["Le CREP est établi aux frais du bailleur.", "Il est annexé au nouveau contrat de location entrant dans le champ décrit par le cours."]}, {"topic": "Cadre de mission", "pages": [83], "id": "o29", "prompt": "Expliquez la spécificité du CREP des parties communes.", "rubric": ["Il concerne les parties communes des immeubles collectifs d’habitation anciens visés, indépendamment d’une transaction.", "Le cours indique l’absence de durée de validité et la nécessité d’entretenir les revêtements."]}, {"topic": "Cadre de mission", "pages": [84], "id": "o30", "prompt": "Quelles sont les deux obligations essentielles décrites après détection de revêtements dégradés au plomb ?", "rubric": ["Informer les occupants et les personnes amenées à intervenir, notamment par remise du CREP.", "Réaliser les travaux appropriés pour supprimer le risque en garantissant la sécurité des occupants."]}, {"topic": "Méthode CREP", "pages": [90], "id": "o31", "prompt": "Présentez les grandes étapes d’un CREP.", "rubric": ["Préparer et identifier la mission et le bien, puis visiter et mesurer.", "Classer les unités de diagnostic et établir le rapport, ses conclusions et recommandations."]}, {"topic": "Méthode CREP", "pages": [92], "id": "o32", "prompt": "Comment traiter un local inaccessible dans le rapport et le croquis ?", "rubric": ["L’énumérer parmi les locaux non visités et indiquer la raison.", "Le faire apparaître sur le croquis avec une désignation claire, sans inventer de mesures."]}, {"topic": "Méthode CREP", "pages": [98], "id": "o33", "prompt": "Quelles qualités doivent avoir la désignation des locaux et le croquis ?", "rubric": ["Les noms doivent être non ambigus et non susceptibles d’évoluer dans le temps.", "Le croquis doit être lisible et identifier les locaux ainsi que les zones."]}, {"topic": "Méthode CREP", "pages": [100], "id": "o34", "prompt": "Définissez un revêtement et citez deux revêtements à considérer.", "rubric": ["Un revêtement est un matériau recouvrant un élément de construction ; le cours inclut les enduits même relativement épais.", "Exemples : peinture, vernis, enduit, feuille de plomb contrecollée, plomb laminé d’étanchéité."]}, {"topic": "Méthode CREP", "pages": [100], "id": "o35", "prompt": "Expliquez pourquoi un revêtement récent ne suffit pas à exclure le plomb.", "rubric": ["Un matériau mince sans plomb peut recouvrir une couche plus ancienne contenant du plomb.", "Il faut donc prendre en compte les couches sous-jacentes et réaliser la recherche prévue."]}, {"topic": "Méthode CREP", "pages": [101], "id": "o36", "prompt": "Distinguez substrat et revêtement, avec un exemple.", "rubric": ["Le substrat est le support, par exemple bois, plâtre, brique ou métal.", "Le revêtement est la couche appliquée sur ce support, par exemple une peinture sur bois."]}, {"topic": "Méthode CREP", "pages": [102], "id": "o37", "prompt": "Pourquoi distingue-t-on les deux faces d’une porte ou fenêtre ?", "rubric": ["Les faces intérieure et extérieure ou appartenant à des locaux différents sont des UD distinctes.", "Elles peuvent avoir des historiques de revêtement différents."]}, {"topic": "Méthode CREP", "pages": [103], "id": "o38", "prompt": "Décrivez le découpage d’une cage d’escalier et citez deux UD distinctes.", "rubric": ["Chaque palier et chaque partie entre deux paliers constituent des locaux distincts.", "Exemples d’UD distinctes : marches, contremarches, balustres, main courante, limon, plafond."]}, {"topic": "Méthode CREP", "pages": [104], "id": "o39", "prompt": "Définissez une unité de diagnostic.", "rubric": ["C’est un ou plusieurs éléments ayant a priori le même substrat.", "Ils ont aussi le même historique en matière de construction et de revêtement."]}, {"topic": "Mesure et classement", "pages": [105], "id": "o40", "prompt": "Comment choisir les points de mesure d’une UD ?", "rubric": ["Rechercher les endroits où la probabilité de présence de plomb est forte, sur une partie saine.", "Si plusieurs mesures sont nécessaires, les réaliser à des endroits différents."]}, {"topic": "Mesure et classement", "pages": [105], "id": "o41", "prompt": "Décrivez la stratégie après une première mesure conclusive positive.", "rubric": ["Une concentration supérieure ou égale à 1 mg/cm² met en évidence la présence au seuil.", "Une seule mesure suffit dans la stratégie décrite pour cette UD."]}, {"topic": "Mesure et classement", "pages": [105], "id": "o42", "prompt": "Décrivez la stratégie après une première mesure inférieure au seuil.", "rubric": ["Effectuer une deuxième mesure sur un autre point de l’UD.", "Si les deux sont négatives mais une UD de même type dans le même local est positive, effectuer une troisième mesure."]}, {"topic": "Mesure et classement", "pages": [107], "id": "o43", "prompt": "Expliquez le choix de la valeur retenue et la répartition des points.", "rubric": ["Retenir la valeur la plus élevée en écartant les valeurs aberrantes.", "Répartir les mesures à des endroits différents pour limiter les faux négatifs."]}, {"topic": "Mesure et classement", "pages": [107], "id": "o44", "prompt": "Comment gérer une mesure non concluante près du seuil ?", "rubric": ["Comparer l’écart au seuil à la précision de l’appareil ; un écart inférieur rend la mesure non concluante selon le cours.", "Renouveler la mesure sur un autre point de l’UD."]}, {"topic": "Mesure et classement", "pages": [108], "id": "o45", "prompt": "Que prévoit le support pour les UD en hauteur ?", "rubric": ["Le diagnostiqueur doit pouvoir mesurer jusqu’à 3 m.", "Au-delà, prévoir des dispositions particulières avec le commanditaire dans le respect des règles de travail."]}, {"topic": "Mesure et classement", "pages": [110], "id": "o46", "prompt": "Distinguez une UD non mesurée d’une UD de classe 0.", "rubric": ["NM signifie non mesurée, avec la raison de l’absence de mesure.", "Une classe 0 suppose une UD mesurée dont la concentration est inférieure au seuil ; les NM ne sont pas classées."]}, {"topic": "Laboratoire", "pages": [111], "id": "o47", "prompt": "Donnez la masse minimale du prélèvement et les couches à inclure.", "rubric": ["Prélever au moins 0,5 g pour permettre l’analyse.", "Inclure l’ensemble des couches de peinture, y compris la plus profonde."]}, {"topic": "Laboratoire", "pages": [111], "id": "o48", "prompt": "Quelles précautions prendre pour un prélèvement de peinture ?", "rubric": ["Éviter substrat et corps étrangers pour ne pas diluer la concentration.", "Limiter la dissémination des poussières en prélevant toutes les couches de peinture."]}, {"topic": "Laboratoire", "pages": [41], "id": "o49", "prompt": "Distinguez les unités des mesures XRF et de l’analyse acido-soluble.", "rubric": ["La XRF donne une concentration surfacique en mg/cm².", "L’analyse acido-soluble donne une concentration massique en mg/g."]}, {"topic": "Laboratoire", "pages": [111], "id": "o50", "prompt": "Expliquez l’intérêt et la limite du prélèvement pour analyse acido-soluble.", "rubric": ["Il simule la solubilisation du plomb dans l’estomac.", "Le prélèvement dégrade la surface, ce qui justifie son caractère exceptionnel."]}, {"topic": "Mesure et classement", "pages": [113], "id": "o51", "prompt": "Distinguez non visible et non dégradé.", "rubric": ["Non visible : la couche au plomb est sous un revêtement sans plomb.", "Non dégradé : le revêtement visible ne présente pas les dégradations considérées."]}, {"topic": "Mesure et classement", "pages": [113], "id": "o52", "prompt": "Distinguez état d’usage et état dégradé.", "rubric": ["L’état d’usage correspond aux dégradations courantes ne générant pas spontanément de poussières ou écailles.", "L’état dégradé correspond à des altérations générant de telles particules, notamment pulvérulence, écaillage ou cloquage."]}, {"topic": "Mesure et classement", "pages": [114], "id": "o53", "prompt": "Donnez les quatre classes d’UD en fonction du résultat et de l’état.", "rubric": ["Classe 0 : sous le seuil ; classe 1 : au seuil ou au-dessus, non visible ou non dégradé.", "Classe 2 : au seuil ou au-dessus, état d’usage ; classe 3 : au seuil ou au-dessus, dégradé."]}, {"topic": "Rapport", "pages": [94], "id": "o54", "prompt": "Citez quatre informations du tableau récapitulatif des mesures.", "rubric": ["Deux informations parmi local, zone, libellé de l’UD, substrat, revêtement, localisation de la mesure.", "Deux autres parmi mesure ou raison de non-mesure, état, dégradation, classement, observations."]}, {"topic": "Rapport", "pages": [96], "id": "o55", "prompt": "Citez quatre éléments de première page du rapport décrits dans le support.", "rubric": ["Deux parmi coordonnées propriétaire/commanditaire, auteur et signature, références d’assurance.", "Deux autres parmi dates, objet, circonstances et champ, occupation, identification de l’appareil utilisé."]}, {"topic": "Radioprotection", "pages": [124], "id": "o56", "prompt": "Expliquez simplement le principe de la fluorescence X.", "rubric": ["La matière excitée par des rayons X réémet notamment des rayons X.", "Le spectre caractéristique permet d’identifier les éléments et d’en déduire leur teneur."]}, {"topic": "Radioprotection", "pages": [129], "id": "o57", "prompt": "Pourquoi contrôler les locaux attenants avant une mesure ?", "rubric": ["Des personnes peuvent se trouver de l’autre côté de la paroi, dans l’axe du faisceau.", "Le risque dépend de la nature, de l’épaisseur de la paroi et de la distance ; empêcher leur présence dans la zone concernée."]}, {"topic": "Radioprotection", "pages": [134], "id": "o58", "prompt": "Citez deux règles de positionnement de l’opérateur.", "rubric": ["Ne jamais orienter l’appareil vers soi ou quelqu’un, ni tenir l’échantillon avec les doigts.", "Se tenir derrière l’appareil, le maintenir éloigné du corps et éviter la partie avant."]}, {"topic": "Radioprotection", "pages": [138], "id": "o59", "prompt": "Nommez et expliquez les trois principes de radioprotection cités.", "rubric": ["Justification : l’exposition doit être nécessaire et apporter un bénéfice ; optimisation : doses aussi basses que raisonnablement possible.", "Limitation : respecter les limites de dose applicables."]}, {"topic": "Radioprotection", "pages": [138], "id": "o60", "prompt": "Comparez tube X et source radioactive au repos.", "rubric": ["Un tube X ne contient pas de source radioactive et n’émet pas de rayons X hors tension.", "Un appareil à source scellée peut émettre un rayonnement résiduel, même obturateur fermé, selon le cours."]}]};
